{
  "name": "New Scale MPM三轴压电微定位台",
  "name_en": "New Scale MPM 3-Axis Piezo Micro-Positioning Stage",
  "manufacturer": "New Scale Technologies",
  "description": "这是一种紧凑型三轴压电微定位模块，可通过网络进行控制，用于在实验中对样品、探针、光学元件或微型机械部件进行高精度位置调整与微米/纳米级运动控制。",
  "description_en": "A compact 3-axis piezoelectric micro-positioning module with network control, used in laboratories for precise positioning and fine motion control of samples, probes, optical components, or small mechanical parts at micrometer to nanometer scale.",
  "tag_hints": [
    "piezo positioning",
    "3-axis stage",
    "micro-positioning",
    "precision alignment",
    "network-controlled stage",
    "microscopy positioning"
  ],
  "actions": [
    {
      "action_name": "auto-axes",
      "description": "获取设备支持的运动轴。",
      "description_en": "Get the motion axes supported by the device."
    },
    {
      "action_name": "auto-capabilities",
      "description": "获取设备的功能能力信息。",
      "description_en": "Get the device capability information."
    },
    {
      "action_name": "auto-stop",
      "description": "立即停止定位台运动。",
      "description_en": "Immediately stop stage motion."
    },
    {
      "action_name": "auto-positionUpdatesPerSecond",
      "description": "获取位置更新频率。",
      "description_en": "Get the position update rate."
    },
    {
      "action_name": "auto-quit",
      "description": "结束对微定位模块的控制会话。",
      "description_en": "End the control session with the micro-positioning module."
    },
    {
      "action_name": "auto-monitor",
      "description": "监测定位台的位置或状态更新。",
      "description_en": "Monitor stage position or status updates."
    }
  ]
}

